//! The LGU panel: raw yearly zonal statistics, static context and PSA official estimates.
//!
//! Every stored value is quantised to `f32` once, when the panel is built (`Panel::push`), so the CLI
//! (reading Parquet), the browser (reading the binary snapshot) and the Worker derive bit-identical
//! features from the same numbers. Arithmetic is `f64`.

// PSA Small Area Estimate rounds used by the models (`ROUNDS`, `CENSUS_EB_FROM`), generated by build.rs from
// config/rounds.json: the VIIRS era (DECISIONS Q4) and, since model v3, the 2006 and 2009 ELL rounds (DECISIONS,
// v3 enhancement), which predate the feature years: their rows have no satellite inputs (NaN) and only start
// transitions and trends. The feature years are not constants: each panel carries the years of its feature
// store (`Panel::first_year`, `Panel::n_years`), and the snapshot records them.
include!(concat!(env!("OUT_DIR"), "/rounds.rs"));

/// Raw yearly inputs per LGU, in this order in the snapshot.
pub const RAW_FIELDS: [&str; 7] = [
    "bm_mean",
    "bm_sum",
    "bm_lit_frac",
    "bm_valid_frac",
    "ndvi_mean",
    "evi_mean",
    "pop",
];
pub const N_RAW: usize = RAW_FIELDS.len();

pub const BM_MEAN: usize = 0;
pub const BM_SUM: usize = 1;
pub const BM_LIT: usize = 2;
pub const BM_VALID: usize = 3;
pub const NDVI: usize = 4;
pub const EVI: usize = 5;
pub const POP: usize = 6;

/// Static context per LGU.
pub const STATIC_FIELDS: [&str; 3] = ["area_km2", "elev_mean", "slope_mean"];
pub const N_STATIC: usize = STATIC_FIELDS.len();

#[inline]
pub fn q(x: f64) -> f64 {
    (x as f32) as f64
}

pub fn round_index(year: i32) -> Option<usize> {
    ROUNDS.iter().position(|&r| r == year)
}

/// One PSA official estimate (poverty incidence, percent).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Official {
    pub estimate: f64,
    pub se: f64,
}

impl Official {
    pub const NONE: Official = Official {
        estimate: f64::NAN,
        se: f64::NAN,
    };
    pub fn is_some(&self) -> bool {
        self.estimate.is_finite()
    }
}

/// Column-oriented panel of all LGUs.
#[derive(Clone, Debug, Default)]
pub struct Panel {
    /// First feature year and number of consecutive feature years (from the feature store).
    pub first_year: i32,
    pub n_years: usize,
    /// HDX pcode digits as an integer (PH0102801 -> 102801); sorted ascending.
    pub ids: Vec<u32>,
    /// Province index per LGU (into `provinces`).
    pub province: Vec<u32>,
    pub provinces: Vec<u32>,
    /// `[lgu][year][field]`, flattened.
    pub raw: Vec<f64>,
    /// `[lgu][field]`, flattened.
    pub statics: Vec<f64>,
    /// `[lgu][round]`, flattened.
    pub officials: Vec<Official>,
    /// PSA provincial poverty incidence from FIES (percent), `[province][round]`, flattened; empty or NaN
    /// when unknown (model v3). Used lagged only: the value of the previous round.
    pub prov_fies: Vec<f64>,
}

/// Province-level context derived from the panel once (CLI, browser and Worker alike).
#[derive(Clone, Debug, Default)]
pub struct ProvinceStats {
    /// Mean official estimate per (province, round) over LGUs with an estimate; NaN if none.
    pub means: Vec<f64>,
    /// FIES provincial poverty incidence minus `means`, centred on the mean over provinces of the same
    /// round (so a nationwide difference between the two sources cancels); NaN when either is missing.
    pub fies_gap: Vec<f64>,
}

impl Panel {
    /// An empty panel over the feature years `first_year..=last_year`.
    pub fn new(first_year: i32, last_year: i32) -> Panel {
        assert!(
            last_year >= first_year,
            "feature years {first_year}..={last_year}"
        );
        Panel {
            first_year,
            n_years: (last_year - first_year + 1) as usize,
            ..Panel::default()
        }
    }

    pub fn last_year(&self) -> i32 {
        self.first_year + self.n_years as i32 - 1
    }

    /// The feature years, ascending.
    pub fn years(&self) -> std::ops::RangeInclusive<i32> {
        self.first_year..=self.last_year()
    }

    pub fn year_index(&self, year: i32) -> Option<usize> {
        self.years()
            .contains(&year)
            .then(|| (year - self.first_year) as usize)
    }

    /// The rounds inside the feature years (what the read models publish as official rounds).
    pub fn published_rounds(&self) -> impl Iterator<Item = i32> + use<> {
        let first = self.first_year;
        ROUNDS.into_iter().filter(move |&r| r >= first)
    }

    pub fn len(&self) -> usize {
        self.ids.len()
    }

    pub fn is_empty(&self) -> bool {
        self.ids.is_empty()
    }

    /// Append one LGU; values are quantised to f32 here (see the module docs).
    pub fn push(
        &mut self,
        id: u32,
        province_id: u32,
        raw: &[f64],
        statics: &[f64],
        officials: &[Official],
    ) {
        assert_eq!(raw.len(), self.n_years * N_RAW);
        assert_eq!(statics.len(), N_STATIC);
        assert_eq!(officials.len(), ROUNDS.len());
        let p = match self.provinces.iter().position(|&x| x == province_id) {
            Some(p) => p,
            None => {
                self.provinces.push(province_id);
                self.provinces.len() - 1
            }
        };
        self.ids.push(id);
        self.province.push(p as u32);
        self.raw.extend(raw.iter().map(|&x| q(x)));
        self.statics.extend(statics.iter().map(|&x| q(x)));
        self.officials.extend(officials.iter().map(|o| Official {
            estimate: q(o.estimate),
            se: q(o.se),
        }));
    }

    pub fn index_of(&self, id: u32) -> Option<usize> {
        self.ids.binary_search(&id).ok()
    }

    #[inline]
    pub fn raw(&self, lgu: usize, year_idx: usize, field: usize) -> f64 {
        self.raw[(lgu * self.n_years + year_idx) * N_RAW + field]
    }

    pub fn raw_year(&self, lgu: usize, year_idx: usize) -> &[f64] {
        let s = (lgu * self.n_years + year_idx) * N_RAW;
        &self.raw[s..s + N_RAW]
    }

    #[inline]
    pub fn stat(&self, lgu: usize, field: usize) -> f64 {
        self.statics[lgu * N_STATIC + field]
    }

    #[inline]
    pub fn official(&self, lgu: usize, round_idx: usize) -> Official {
        self.officials[lgu * ROUNDS.len() + round_idx]
    }

    /// The latest round strictly before `year` with an official estimate for this LGU.
    pub fn prev_round(&self, lgu: usize, year: i32) -> Option<usize> {
        (0..ROUNDS.len())
            .rev()
            .find(|&r| ROUNDS[r] < year && self.official(lgu, r).is_some())
    }

    pub fn fies(&self, province: usize, round_idx: usize) -> f64 {
        self.prov_fies
            .get(province * ROUNDS.len() + round_idx)
            .copied()
            .unwrap_or(f64::NAN)
    }

    /// Sets the FIES provincial figure (quantised to f32 like every stored value).
    pub fn set_fies(&mut self, province: usize, round_idx: usize, value: f64) {
        if self.prov_fies.len() != self.provinces.len() * ROUNDS.len() {
            self.prov_fies = vec![f64::NAN; self.provinces.len() * ROUNDS.len()];
        }
        self.prov_fies[province * ROUNDS.len() + round_idx] = q(value);
    }

    pub fn province_stats(&self) -> ProvinceStats {
        let means = self.province_round_means();
        let nr = ROUNDS.len();
        let mut gap: Vec<f64> = (0..means.len())
            .map(|k| self.fies(k / nr, k % nr) - means[k])
            .collect();
        for r in 0..nr {
            let v: Vec<f64> = (0..self.provinces.len())
                .map(|p| gap[p * nr + r])
                .filter(|x| x.is_finite())
                .collect();
            let c = v.iter().sum::<f64>() / v.len().max(1) as f64;
            for p in 0..self.provinces.len() {
                gap[p * nr + r] = q(gap[p * nr + r] - c);
            }
        }
        ProvinceStats {
            means,
            fies_gap: gap,
        }
    }

    /// Mean official estimate per (province, round) over LGUs with an estimate; NaN if none.
    pub fn province_round_means(&self) -> Vec<f64> {
        let np = self.provinces.len();
        let mut sum = vec![0.0f64; np * ROUNDS.len()];
        let mut n = vec![0u32; np * ROUNDS.len()];
        for i in 0..self.len() {
            let p = self.province[i] as usize;
            for r in 0..ROUNDS.len() {
                let o = self.official(i, r);
                if o.is_some() {
                    sum[p * ROUNDS.len() + r] += o.estimate;
                    n[p * ROUNDS.len() + r] += 1;
                }
            }
        }
        sum.iter()
            .zip(&n)
            .map(|(s, &k)| if k > 0 { q(s / k as f64) } else { f64::NAN })
            .collect()
    }
}
